pragma solidity >=0.8.0;

error BadValue(bytes32 tag, address a, address b);

contract AddrRevertProbe {
    uint256 public count;

    function bump() internal {
        count += 1;
    }

    function failAddr(bytes32 tag, address expected) public {
        bump();
        revert BadValue(tag, msg.sender, expected);
    }

    function failAddrZero(bytes32 tag) public {
        bump();
        revert BadValue(tag, msg.sender, address(0));
    }

    function failAddrHigh(bytes32 tag) public {
        address high = address(uint160(0x8000000000000000000000000000000000000000));
        bump();
        revert BadValue(tag, high, msg.sender);
    }
}
